50	// Abstraction describing the binding of Nodes to cycles for a FunctionBase.
51	class PipelineSchedule {
52	 public:
53	  PipelineSchedule() = default;
54	
55	  // Reconstructs a PipelineSchedule object from a proto representation.
56	  static absl::StatusOr<PipelineSchedule> FromProto(
57	      FunctionBase* function, const PackageScheduleProto& proto);
58	
59	  // Builds trivial pipeline schedule with all nodes in a single stage
60	  static absl::StatusOr<PipelineSchedule> SingleStage(FunctionBase* function);
61	
62	  struct Options {
63	    std::optional<int64_t> length;
64	    std::optional<int64_t> min_clock_period_ps;
65	    std::optional<int64_t> target_clock_period_ps;
66	  };
67	
68	  // Constructs a schedule for the given function with the given cycle map. If
69	  // length is not given in `options`, then the length is equal to the largest
70	  // cycle in cycle map minus one.
71	  static absl::StatusOr<PipelineSchedule> Create(FunctionBase* function_base,
72	                                                 ScheduleCycleMap cycle_map,
73	                                                 Options options = {});
74	
75	  FunctionBase* function_base() const { return function_base_; }
76	
77	  // Returns whether the given node is contained in this schedule.
78	  bool IsScheduled(Node* node) const { return cycle_map_.contains(node); }
79	
80	  // Remove a node from the schedule.
81	  void RemoveNode(Node* node);
82	
83	  // Returns the cycle in which the node is placed. Dies if node has not
84	  // been placed in this schedule.
85	  int64_t cycle(const Node* node) const { return cycle_map_.at(node); }
86	
87	  bool empty() const { return cycle_map_.empty(); }
88	
89	  // Returns the nodes scheduled in the given cycle. The node order is
90	  // guaranteed to be topological.
91	  absl::Span<Node* const> nodes_in_cycle(int64_t cycle) const;
92	
93	  std::string ToString() const;
94	
95	  // Computes and returns the set of Nodes which are live out of the given
96	  // cycle. A node is live out of cycle N if it is scheduled at or before cycle
97	  // N and has users after cycle N.
98	  std::vector<Node*> GetLiveOutOfCycle(int64_t c) const;
99	
100	  // Returns true if the given node is live out of the given cycle.
101	  bool IsLiveOutOfCycle(Node* node, int64_t c) const;
102	
103	  // Returns the number of stages in the pipeline. Use 'length' instead of
104	  // 'size' as 'size' is ambiguous in this context (number of resources? number
105	  // of nodes? number of cycles?). Note that codegen may add flops to the input
106	  // or output of the pipeline so this value may not be the same as the latency
107	  // of the pipeline.
108	  int64_t length() const { return cycle_to_nodes_.size(); }
109	
110	  // Returns the minimum possible clock period, if this was computed while
111	  // creating the schedule. This is purely for tracing purposes.
112	  const std::optional<int64_t>& min_clock_period_ps() const {
113	    return min_clock_period_ps_;
114	  }
115	
116	  const std::optional<int64_t>& target_clock_period_ps() const {
117	    return target_clock_period_ps_;
118	  }
119	
120	  // Verifies various invariants of the schedule (each node scheduled exactly
121	  // once, node not scheduled before operands, etc.).
122	  absl::Status Verify() const;
123	
124	  // Verifies that no path of nodes scheduled in the same cycle exceeds the
125	  // given clock period.
126	  absl::Status VerifyTiming(int64_t clock_period_ps,
127	                            const DelayEstimator& delay_estimator) const;
128	  absl::Status VerifyTiming(int64_t clock_period_ps,
129	                            const DelayManager& delay_manager) const;
130	
131	  // Verifies that all scheduling constraints are followed.
132	  absl::Status VerifyConstraints(
133	      absl::Span<const SchedulingConstraint> constraints,
134	      const SchedulingOptions& options) const;
135	
136	  // Returns a protobuf holding this object's scheduling info.
137	  absl::StatusOr<PipelineScheduleProto> ToProto(
138	      const DelayEstimator& delay_estimator) const;
139	
140	  // Returns the number of internal registers in this schedule.
141	  int64_t CountFinalInteriorPipelineRegisters() const;
142	
143	  // Returns the underlying cycle map.
144	  const ScheduleCycleMap& GetCycleMap() const { return cycle_map_; }
145	
146	 private:
147	  PipelineSchedule(FunctionBase* function_base, ScheduleCycleMap cycle_map,
148	                   std::optional<int64_t> min_clock_period_ps,
149	                   std::optional<int64_t> target_clock_period_ps);
150	
151	  FunctionBase* function_base_ = nullptr;
152	
153	  // Map from node to the cycle in which it is scheduled.
154	  ScheduleCycleMap cycle_map_;
155	
156	  // The nodes scheduled each cycle.
157	  std::vector<std::vector<Node*>> cycle_to_nodes_;
158	
159	  // The minimum possible clock period, if known.
160	  std::optional<int64_t> min_clock_period_ps_;
161	
162	  // The actual target clock period used for scheduling.
163	  std::optional<int64_t> target_clock_period_ps_;
164	};
