166	// A collection of FunctionBase schedules necessary to generate pipelined
167	// implementation for a Package.
168	class PackageSchedule {
169	 public:
170	  using ScheduleMap = absl::flat_hash_map<FunctionBase*, PipelineSchedule>;
171	
172	  explicit PackageSchedule(Package* package) : package_(package) {}
173	
174	  explicit PackageSchedule(PipelineSchedule schedule)
175	      : package_(schedule.function_base()->package()) {
176	    schedules_[schedule.function_base()] = std::move(schedule);
177	  }
178	  PackageSchedule(Package* package, ScheduleMap schedules,
179	                  std::optional<absl::flat_hash_map<FunctionBase*, int64_t>>
180	                      synchronous_offsets = std::nullopt)
181	      : package_(package),
182	        schedules_(std::move(schedules)),
183	        synchronous_offsets_(synchronous_offsets) {}
184	
185	  // Reconstructs a PackageSchedule object from a proto representation.
186	  // Will return an error status if the proto schedules reference nodes that
187	  // don't exist in the package.
188	  static absl::StatusOr<PackageSchedule> FromProto(
189	      Package* p, const PackageScheduleProto& proto);
190	
191	  // Returns whether the given FunctionBase has a schedule.
192	  bool HasSchedule(FunctionBase* fb) const { return schedules_.contains(fb); }
193	
194	  const ScheduleMap& GetSchedules() const { return schedules_; }
195	
196	  // Return the PipelineSchedule for the given FunctionBase.
197	  PipelineSchedule& GetSchedule(FunctionBase* function_base) {
198	    return schedules_.at(function_base);
199	  }
200	  const PipelineSchedule& GetSchedule(FunctionBase* function_base) const {
201	    return schedules_.at(function_base);
202	  }
203	
204	  // Adds a schedule for the given FunctionBase. Returns an error if there is
205	  // already a schedule for the given FunctionBase.
206	  absl::Status AddSchedule(FunctionBase* fb, PipelineSchedule&& schedule) {
207	    XLS_RET_CHECK(!HasSchedule(fb))
208	        << absl::StrFormat("`%s` already has a schedule", fb->name());
209	    XLS_RET_CHECK_EQ(fb, schedule.function_base());
210	    schedules_[fb] = schedule;
211	    return absl::OkStatus();
212	  }
213	
214	  absl::Status RemoveSchedule(FunctionBase* fb) {
215	    if (!HasSchedule(fb)) {
216	      return absl::NotFoundError(
217	          absl::StrFormat("FunctionBase `%s` has no schedule", fb->name()));
218	    }
219	    schedules_.erase(fb);
220	    if (synchronous_offsets_.has_value()) {
221	      synchronous_offsets_->erase(fb);
222	    }
223	    return absl::OkStatus();
224	  }
225	
226	  // Sets the schedule associated with `fb` to `schedule`.
227	  absl::Status UpdateSchedule(FunctionBase* fb, PipelineSchedule&& schedule) {
228	    if (HasSchedule(fb)) {
229	      XLS_RETURN_IF_ERROR(RemoveSchedule(fb));
230	    }
231	    return AddSchedule(fb, std::move(schedule));
232	  }
233	
234	  // Returns the FunctionBases with a schedule in a stable sort.
235	  std::vector<FunctionBase*> GetScheduledFunctionBases() const {
236	    std::vector<FunctionBase*> function_bases;
237	    for (const auto& [fb, _] : schedules_) {
238	      function_bases.push_back(fb);
239	    }
240	    std::sort(function_bases.begin(), function_bases.end(),
241	              FunctionBase::NameLessThan);
242	    return function_bases;
243	  }
244	
245	  bool IsSynchronousSchedule() const {
246	    return synchronous_offsets_.has_value();
247	  }
248	
249	  // Returns the global stage the nodes is in within a synchronous schedule of
250	  // the package. CHECK fails if this is PackageSchedule is not a synchronous
251	  // schedule.
252	  int64_t GetSynchronousCycle(Node* node) const {
253	    CHECK(IsSynchronousSchedule());
254	    return GetSchedule(node->function_base()).cycle(node) +
255	           synchronous_offsets_->at(node->function_base());
256	  }
257	
258	  void Clear() {
259	    schedules_.clear();
260	    synchronous_offsets_.reset();
261	  }
262	
263	  absl::StatusOr<PackageScheduleProto> ToProto(
264	      const DelayEstimator& delay_estimator) const;
265	  std::string ToString() const;
266	
267	  using GenericFunctionInterfaceProto =
268	      std::variant<PackageInterfaceProto::Function,
269	                   PackageInterfaceProto::Proc>;
270	  // Generates an interface proto describing the results of scheduling for the
271	  // given function base.
272	  absl::StatusOr<PackageInterfaceProto::ScheduledFunctionBase>
273	  ToScheduledInterfaceProto(FunctionBase* fb,
274	                            GenericFunctionInterfaceProto base_info) const;
275	
276	 private:
277	  Package* package_ = nullptr;
278	  ScheduleMap schedules_;
279	
280	  // If this package represents a synchronous schedule of FunctionBases
281	  // (procs) in the package, this map contains the stage offset of each
282	  // function base in the synchronous schedule.
283	  std::optional<absl::flat_hash_map<FunctionBase*, int64_t>>
284	      synchronous_offsets_;
285	};
286	
287	}  // namespace xls
288	
289	#endif  // XLS_SCHEDULING_PIPELINE_SCHEDULE_H_
