88	// This represents a constraint saying that interactions on the given
89	// `source_channel` of the type specified by the given `source_direction`
90	// must occur between `minimum_latency` and `maximum_latency` (inclusive) cycles
91	// before interactions on the given `target_channel` of the type specified by
92	// the given `target_direction`.
93	class IOConstraint {
94	 public:
95	  IOConstraint(std::string_view source_channel, IODirection source_direction,
96	               std::string_view target_channel, IODirection target_direction,
97	               int64_t minimum_latency, int64_t maximum_latency)
98	      : source_channel_(source_channel),
99	        source_direction_(source_direction),
100	        target_channel_(target_channel),
101	        target_direction_(target_direction),
102	        minimum_latency_(minimum_latency),
103	        maximum_latency_(maximum_latency) {}
104	
105	  std::string SourceChannel() const { return source_channel_; }
106	
107	  IODirection SourceDirection() const { return source_direction_; }
108	
109	  std::string TargetChannel() const { return target_channel_; }
110	
111	  IODirection TargetDirection() const { return target_direction_; }
112	
113	  int64_t MinimumLatency() const { return minimum_latency_; }
114	
115	  int64_t MaximumLatency() const { return maximum_latency_; }
116	
117	  friend bool operator==(const IOConstraint& lhs, const IOConstraint& rhs) {
118	    return lhs.source_channel_ == rhs.source_channel_ &&
119	           lhs.source_direction_ == rhs.source_direction_ &&
120	           lhs.target_channel_ == rhs.target_channel_ &&
121	           lhs.target_direction_ == rhs.target_direction_ &&
122	           lhs.minimum_latency_ == rhs.minimum_latency_ &&
123	           lhs.maximum_latency_ == rhs.maximum_latency_;
124	  }
125	  friend bool operator!=(const IOConstraint& lhs, const IOConstraint& rhs) {
126	    return !(lhs == rhs);
127	  }
128	
129	  template <typename H>
130	  friend H AbslHashValue(H h, const IOConstraint& s) {
131	    return H::combine(std::move(h), s.source_channel_, s.source_direction_,
132	                      s.target_channel_, s.target_direction_,
133	                      s.minimum_latency_, s.maximum_latency_);
134	  }
135	
136	  template <typename Sink>
137	  friend void AbslStringify(Sink& sink, const IOConstraint& constraint) {
138	    auto dir_to_string = [](IODirection dir) {
139	      return dir == IODirection::kSend ? "send" : "recv";
140	    };
141	    auto min_limit_to_string = [](int64_t limit) -> std::string {
142	      if (limit == std::numeric_limits<int64_t>::min()) {
143	        return "none";
144	      }
145	      return absl::StrCat(limit);
146	    };
147	    auto max_limit_to_string = [](int64_t limit) -> std::string {
148	      if (limit == std::numeric_limits<int64_t>::max()) {
149	        return "none";
150	      }
151	      return absl::StrCat(limit);
152	    };
153	    absl::Format(&sink, "%s:%s:%s:%s:%s:%s", constraint.source_channel_,
154	                 dir_to_string(constraint.source_direction_),
155	                 constraint.target_channel_,
156	                 dir_to_string(constraint.target_direction_),
157	                 min_limit_to_string(constraint.minimum_latency_),
158	                 max_limit_to_string(constraint.maximum_latency_));
159	  }
160	
161	  friend std::ostream& operator<<(std::ostream& os,
162	                                  const IOConstraint& constraint) {
163	    os << absl::StreamFormat("%v", constraint);
164	    return os;
165	  }
166	
167	 private:
168	  std::string source_channel_;
169	  IODirection source_direction_;
170	  std::string target_channel_;
171	  IODirection target_direction_;
172	  int64_t minimum_latency_;
173	  int64_t maximum_latency_;
174	};
