29	#include "absl/log/log.h"
30	#include "absl/status/status.h"
31	#include "absl/status/statusor.h"
32	#include "absl/strings/str_format.h"
33	#include "absl/types/span.h"
34	#include "xls/common/visitor.h"
35	#include "xls/estimators/delay_model/delay_estimator.h"
36	#include "xls/ir/ir_annotator.h"
37	#include "xls/ir/node.h"
38	#include "xls/scheduling/schedule_graph.h"
39	#include "xls/scheduling/scheduling_options.h"
40	
41	namespace xls {
42	namespace sched {
43	
44	// An abstraction holding lower and upper bounds for each node in a
45	// function. The bounds are constraints on cycles in which a node may be
46	// scheduled.
47	class ScheduleBounds {
48	 public:
49	  // By default how many cycles we are willing to even attempt to schedule in.
50	  // We set this to 1 billion since that is far larger than any even
51	  // unreasonable design would require and is still small enough that we don't
52	  // need to deal with overflow issues when implementing bounds.
53	  //
54	  // TODO(allight): It would be nice to make this fully overflow-safe.
55	  static constexpr int64_t kDefaultMaxUpperBound = 1000000000;
56	
57	  // A simplified representation of a scheduling constraint. These are always
58	  // expressed in terms of relations between individual nodes.
59	  //
60	  // A constraint is one of the following:
61	  // * A `NodeInCycleConstraint` that constrains a node to be scheduled in a
62	  //   specific cycle.
63	  // * A `NodeDifferenceConstraint` that constrains the 'subject' node to be
64	  // between 'min_after' and 'max_after' cycles after the 'anchor' node
65	  // (inclusive on both ends).
66	  // * A `LastStageConstraint` that constrains a node to be scheduled in the
67	  //   last stage of the pipeline.
68	  class NodeSchedulingConstraint {
69	   public:
70	    // Constraint that a node must be in the last stage of the pipeline
71	    struct LastStageConstraint {
72	      Node* node;
73	
74	      template <typename Sink>
75	      friend void AbslStringify(Sink& sink,
76	                                const LastStageConstraint& constraint) {
77	        absl::Format(&sink, "%s:last_stage", constraint.node->GetName());
78	      }
79	      friend std::ostream& operator<<(std::ostream& os,
80	                                      const LastStageConstraint& constraint) {
81	        os << absl::StreamFormat("%v", constraint);
82	        return os;
83	      }
84	    };
85	    struct NodeDifferenceConstraint {
86	      // The node which defines where 'subject' can be placed.
87	      Node* const anchor;
88	      // This node is constrained to be scheduled at least
89	      // `min_difference` cycles after the first node and at most
90	      // `max_difference` cycles after the first node.
91	      Node* const subject;
92	      // The minimum number of cycles the second node must be scheduled after
93	      // the first node. Must be non-negative.
94	      int64_t min_after;
95	      int64_t max_after;
96	
97	      template <typename Sink>
98	      friend void AbslStringify(Sink& sink,
99	                                const NodeDifferenceConstraint& constraint) {
100	        absl::Format(&sink, "%s - %s ∈ [%d, %d]", constraint.subject->GetName(),
101	                     constraint.anchor->GetName(), constraint.min_after,
102	                     constraint.max_after);
103	      }
104	      friend std::ostream& operator<<(
105	          std::ostream& os, const NodeDifferenceConstraint& constraint) {
106	        os << absl::StreamFormat("%v", constraint);
107	        return os;
108	      }
109	    };
110	    using InnerConstraints =
111	        std::variant<NodeInCycleConstraint, NodeDifferenceConstraint,
112	                     LastStageConstraint>;
113	
114	    NodeSchedulingConstraint(const InnerConstraints& inner_constraints,
115	                             bool is_lower_bound_constraint = true)
116	        : inner_constraints_(inner_constraints),
117	          is_lower_bound_constraint_(is_lower_bound_constraint) {}
118	
119	    bool is_lower_bound_constraint() const {
120	      return is_lower_bound_constraint_;
121	    }
122	    operator const InnerConstraints&() const { return inner_constraints_; }
123	    // Get the node which is constrained.
124	    Node* subject() const {
125	      return std::visit(
126	          Visitor{
127	              [](const LastStageConstraint& lsc) { return lsc.node; },
128	              [](const NodeDifferenceConstraint& ndc) { return ndc.subject; },
129	              [](const NodeInCycleConstraint& nicc) { return nicc.GetNode(); },
130	          },
131	          inner_constraints_);
132	    }
133	
134	    template <typename T>
135	      requires(std::is_same_v<T, NodeInCycleConstraint> ||
136	               std::is_same_v<T, NodeDifferenceConstraint> ||
137	               std::is_same_v<T, LastStageConstraint>)
138	    bool Is() const {
139	      return std::holds_alternative<T>(inner_constraints_);
140	    }
141	
142	    template <typename T>
143	      requires(std::is_same_v<T, NodeInCycleConstraint> ||
144	               std::is_same_v<T, NodeDifferenceConstraint> ||
145	               std::is_same_v<T, LastStageConstraint>)
146	    T As() const {
147	      CHECK(Is<T>()) << "Unexpected constraint type";
148	      return std::get<T>(inner_constraints_);
149	    }
150	
151	    NodeSchedulingConstraint Reverse(int64_t max_upper_bound) const {
152	      return std::visit(
153	          Visitor{
154	              [&](const LastStageConstraint& lsc) {
155	                // Last stage constraints need to be handled differently for
156	                // upper and lower bounds.
157	                return NodeSchedulingConstraint(lsc,
158	                                                !is_lower_bound_constraint_);
159	              },
160	              [&](const NodeInCycleConstraint& nicc) {
161	                return NodeSchedulingConstraint(
162	                    NodeInCycleConstraint{nicc.GetNode(),
163	                                          max_upper_bound - nicc.GetCycle()},
164	                    !is_lower_bound_constraint_);
165	              },
166	              [&](const NodeDifferenceConstraint& ndc) {
167	                return NodeSchedulingConstraint(
168	                    NodeDifferenceConstraint{
169	                        .anchor = ndc.subject,
170	                        .subject = ndc.anchor,
171	                        .min_after = ndc.min_after,
172	                        .max_after = ndc.max_after,
173	                    },
174	                    !is_lower_bound_constraint_);
175	              },
176	          },
177	          inner_constraints_);
178	    }
179	
180	    template <typename Sink>
181	    friend void AbslStringify(Sink& sink,
182	                              const NodeSchedulingConstraint& constraint) {
183	      std::visit(Visitor{
184	                     [&](const LastStageConstraint& lsc) {
185	                       absl::Format(&sink, "%v", lsc);
186	                     },
187	                     [&](const NodeDifferenceConstraint& ndc) {
188	                       absl::Format(&sink, "%v", ndc);
189	                     },
190	                     [&](const NodeInCycleConstraint& nicc) {
191	                       absl::Format(&sink, "%v", nicc);
192	                     },
193	                 },
194	                 constraint.inner_constraints_);
195	    }
196	    friend std::ostream& operator<<(
197	        std::ostream& os, const NodeSchedulingConstraint& constraint) {
198	      os << absl::StreamFormat("%v", constraint);
199	      return os;
200	    }
201	
202	   private:
203	    InnerConstraints inner_constraints_;
204	    bool is_lower_bound_constraint_ = true;
205	  };
206	
207	  // Returns a object with the lower bounds of each node set to the earliest
208	  // possible cycle which satisfies dependency and clock period constraints.
209	  // Similarly, upper bounds are set to the latest possible cycle The upper
210	  // bounds of nodes with no uses (leaf nodes) are set to the maximum lower
211	  // bound of any node. Note this never considers nodes 'dead-after-synthesis'
212	  // if they are returned by the schedule_util.h 'GetDeadAfterSynthesisNodes'
213	  // function.
214	  static absl::StatusOr<ScheduleBounds> ComputeAsapAndAlapBounds(
215	      FunctionBase* f, int64_t clock_period_ps,
216	      const DelayEstimator& delay_estimator,
217	      std::optional<int64_t> ii = std::nullopt,
218	      absl::Span<SchedulingConstraint const> constraints = {},
219	      int64_t max_upper_bound = kDefaultMaxUpperBound);
220	  // Same as ComputeAsapAndAlapBounds but takes NodeSchedulingConstraints
221	  // directly. This is for testing.
222	  static absl::StatusOr<ScheduleBounds> ComputeAsapAndAlapBounds(
223	      FunctionBase* f, int64_t clock_period_ps,
224	      const DelayEstimator& delay_estimator,
225	      absl::Span<NodeSchedulingConstraint const> constraints,
226	      int64_t max_upper_bound = kDefaultMaxUpperBound);
227	
228	  // Upon construction all parameters have lower and upper bounds of 0. All
229	  // other nodes have a lower bound of 1 and an upper bound of
230	  // 'max_upper_bound' (defaults to kDefaultMaxUpperBound or 1 billion).
231	  static absl::StatusOr<ScheduleBounds> Create(
232	      ScheduleGraph graph, int64_t clock_period_ps,
233	      const DelayEstimator& delay_estimator,
234	      std::optional<int64_t> ii = std::nullopt,
235	      absl::Span<SchedulingConstraint const> constraints = {},
236	      int64_t max_upper_bound = kDefaultMaxUpperBound);
237	
238	  ScheduleBounds(const ScheduleBounds& other) = default;
239	  ScheduleBounds(ScheduleBounds&& other) = default;
240	  ScheduleBounds& operator=(const ScheduleBounds& other) = default;
241	  ScheduleBounds& operator=(ScheduleBounds&& other) = default;
242	
243	  // Resets node bounds to their initial unconstrained values.
244	  void Reset();
245	
246	  const ScheduleGraph& graph() const { return graph_; }
247	
248	  // Return the lower/upper bound of the given node.
249	  int64_t lb(Node* node) const { return bounds_.at(node).after_min; }
250	  int64_t ub(Node* node) const {
251	    return max_upper_bound_ - bounds_.at(node).before_max;
252	  }
253	
254	  // Return the lower and upper bound as a pair (lower bound is first element).
255	  std::pair<int64_t, int64_t> bounds(Node* node) const {
256	    NodeBound b = bounds_.at(node);
257	    return std::make_pair(b.after_min, max_upper_bound_ - b.before_max);
258	  }
259	
260	  // Sets the lower bound of the given node to the maximum of its existing value
261	  // and the given value. Raises a ResourceExhaustedError if the new value
262	  // results in infeasible bounds (lower bound is greater than upper bound).
263	  absl::Status TightenNodeLb(Node* node, int64_t value) {
264	    VLOG(2) << "TightenNodeLb: " << node->GetName() << " to " << value;
265	    return TightenNodeLbInternal(node, value).status();
266	  }
267	
268	  // Sets the upper bound of the given node to the minimum of its existing value
269	  // and the given value. Raises a ResourceExhaustedError if the new value
270	  // results in infeasible bounds (lower bound is greater than upper bound).
271	  absl::Status TightenNodeUb(Node* node, int64_t value) {
272	    VLOG(2) << "TightenNodeUb: " << node->GetName() << " to " << value;
273	    return TightenNodeUbInternal(node, value).status();
274	  }
275	
276	  // Returns the maximum lower (upper) bound of any node in the function.
277	  int64_t max_lower_bound() const { return max_lower_bound_; }
278	  int64_t min_upper_bound() const {
279	    return max_upper_bound_ - max_before_upper_bound_;
280	  }
281	
282	  std::string ToString() const;
283	
284	  // Uses the set bounds and constraints to attempt to tighten the bounds of
285	  // each node such that all constraints, including explicit constraints,
286	  // clock-period and dependency constraints, are satisfied. If 'fuel' is given,
287	  // then the constraint propagation will stop after 'fuel' constraint
288	  // applications. If 'fuel' is not given, then the bounds will be propagated
289	  // until no more tightening is possible. Returns an error if the bounds are
290	  // infeasible or fail to converge to a constraint-compatible state.
291	  //
292	  // Should be called after calling TightenNodeLb (TightenNodeUb) to propagate
293	  // the tightened bound throughout the graph. This method only tightens bounds
294	  // (increases lower bounds and decreases upper bounds). Returns an error if
295	  // propagation results in infeasible bounds (lower bound is greater than upper
296	  // bound for a node).
297	  absl::Status PropagateBounds(std::optional<int64_t> fuel = 6);
298	
299	  // Force all constraints to be given in terms of nodes. Public for testing.
300	  static absl::StatusOr<std::vector<NodeSchedulingConstraint>>
301	  ConvertSchedulingConstraints(
302	      ScheduleGraph& graph, absl::Span<const SchedulingConstraint> constraints,
303	      std::optional<int64_t> ii, int64_t max_upper_bound);
304	
305	  // Create using NodeSchedulingConstraints. Public for testing.
306	  //
307	  // All constraints must be constraints suitable for 'lower-bound' propagation.
308	  static absl::StatusOr<ScheduleBounds> Create(
309	      ScheduleGraph graph, int64_t clock_period_ps,
310	      const DelayEstimator& delay_estimator,
311	      absl::Span<NodeSchedulingConstraint const> constraints,
312	      int64_t max_upper_bound = kDefaultMaxUpperBound);
313	
314	  // Add a new constraint to the set of constraints.
315	  void AddConstraint(NodeSchedulingConstraint constraint) {
316	    auto lower_bound = constraint.is_lower_bound_constraint()
317	                           ? constraint
318	                           : constraint.Reverse(max_upper_bound_);
319	    auto upper_bound = constraint.is_lower_bound_constraint()
320	                           ? constraint.Reverse(max_upper_bound_)
321	                           : constraint;
322	    constraints_by_subject_lower_bound_[lower_bound.subject()].push_back(
323	        lower_bound);
324	    constraints_by_subject_upper_bound_[upper_bound.subject()].push_back(
325	        upper_bound);
326	    VLOG(2) << "Added constraint: " << constraint << " to "
327	            << lower_bound.subject()->GetName();
328	  }
329	  // Add a new lower-bound constraint to the set of constraints.
330	  void AddConstraint(NodeSchedulingConstraint::InnerConstraints constraint,
331	                     bool is_lower_bound_constraint = true) {
332	    AddConstraint(
333	        NodeSchedulingConstraint(constraint, is_lower_bound_constraint));
334	  }
335	
336	  // A node's bounds, stored as a {lower, upper} pair.
337	  struct NodeBound {
338	    // How many cycles after the 0'th cycle a node must be.
339	    int64_t after_min = 0;
340	    // How many cycles before the last'th cycle a node must be.
341	    int64_t before_max = 0;
342	  };
343	
344	 private:
345	  ScheduleBounds(
346	      ScheduleGraph graph, int64_t clock_period_ps,
347	      const DelayEstimator& delay_estimator,
348	      absl::flat_hash_map<Node*, std::vector<NodeSchedulingConstraint>>
349	          constraints_by_subject_lower_bound,
350	      absl::flat_hash_map<Node*, std::vector<NodeSchedulingConstraint>>
351	          constraints_by_subject_upper_bound,
352	      int64_t max_upper_bound)
353	      : graph_(std::move(graph)),
354	        clock_period_ps_(clock_period_ps),
355	        delay_estimator_(&delay_estimator),
356	        constraints_by_subject_lower_bound_(
357	            std::move(constraints_by_subject_lower_bound)),
358	        constraints_by_subject_upper_bound_(
359	            std::move(constraints_by_subject_upper_bound)),
360	        max_upper_bound_(max_upper_bound) {
361	    Reset();
362	  }
363	
364	  absl::StatusOr<int64_t> GetDelay(Node* node) const;
365	
366	  // Updates the lower (upper) bounds of each node such that dependency and
367	  // clock period constraints are met for every node. Should be called after
368	  // calling TightenNodeLb (TightenNodeUb) to propagate the tightened bound
369	  // throughout the graph. This method only tightens bounds (increases lower
370	  // bounds and decreases upper bounds). Returns an error if propagation results
371	  // in infeasible bounds (lower bound is greater than upper bound for a node).
372	  absl::StatusOr<bool> PropagateLowerBounds();
373	  absl::StatusOr<bool> PropagateUpperBounds();
374	  absl::StatusOr<bool> PropagateConstraints();
375	  absl::Status CheckConstraints(std::optional<int64_t> fuel, bool stabilized);
376	  absl::Status CheckBasicBounds();
377	  absl::StatusOr<bool> TightenNodeLbInternal(Node* node, int64_t value) {
378	    if (value > ub(node)) {
379	      return absl::ResourceExhaustedError(
380	          absl::StrFormat("Unable to tighten the lower bound of node %s to %d.",
381	                          node->GetName(), value));
382	    }
383	    int64_t initial = lb(node);
384	    bounds_.at(node).after_min = std::max(lb(node), value);
385	    max_lower_bound_ = std::max(max_lower_bound_, value);
386	    return initial < value;
387	  }
388	  absl::StatusOr<bool> TightenNodeUbInternal(Node* node, int64_t value) {
389	    if (value < lb(node)) {
390	      return absl::ResourceExhaustedError(
391	          absl::StrFormat("Unable to tighten the upper bound of node %s to %d "
392	                          "(current lb: %d).",
393	                          node->GetName(), value, lb(node)));
394	    }
395	    int64_t initial = ub(node);
396	    bounds_.at(node).before_max = max_upper_bound_ - std::min(initial, value);
397	    VLOG(3) << "TightenNodeUbInternal: " << node->GetName() << " to " << value
398	            << " initial: " << initial << " new ub: " << ub(node);
399	    return initial > value;
400	  }
401	
402	  ScheduleGraph graph_;
403	  int64_t clock_period_ps_;
404	  const DelayEstimator* delay_estimator_;
405	
406	  // Map from each node to all of the scheduling constraints that the node is
407	  // subject to.
408	  absl::flat_hash_map<Node*, std::vector<NodeSchedulingConstraint>>
409	      constraints_by_subject_lower_bound_;
410	  // Constraints specifically on the upper bound. This reverses the
411	  // direction of the NodeDifferenceConstraint to put the subject first.
412	  absl::flat_hash_map<Node*, std::vector<NodeSchedulingConstraint>>
413	      constraints_by_subject_upper_bound_;
414	
415	  // The bounds of each node stored as a {lower, upper} pair.
416	  absl::flat_hash_map<Node*, NodeBound> bounds_;
417	  absl::flat_hash_map<Node*, int64_t> explicit_upper_bounds_;
418	
419	  int64_t max_lower_bound_;
420	  int64_t max_before_upper_bound_;
421	  // The maximum upper bound of any node in the function. This is what we use as
422	  // the zero point for upper bounds.
423	  // Const after construction.
424	  int64_t max_upper_bound_ = kDefaultMaxUpperBound;
425	};
426	
427	class ScheduleBoundsAnnotator : public IrAnnotator {
428	 public:
429	  explicit ScheduleBoundsAnnotator(const ScheduleBounds& bounds)
430	      : bounds_(std::move(bounds)) {}
431	  Annotation NodeAnnotation(Node* node) const override;
432	
433	 private:
434	  const ScheduleBounds& bounds_;
435	};
436	
437	}  // namespace sched
438	}  // namespace xls
439	
440	#endif  // XLS_SCHEDULING_SCHEDULE_BOUNDS_H_
