49	
50	// Splits the nodes at the boundary between 'cycle' and 'cycle + 1' by
51	// performing a minimum cost cut and tightens the bounds accordingly. Upon
52	// return no node in the function will have a range which spans both 'cycle' and
53	// 'cycle + 1'.
54	absl::Status SplitAfterCycle(FunctionBase* f, int64_t cycle,
55	                             const DelayEstimator& delay_estimator,
56	                             sched::ScheduleBounds* bounds) {
57	  VLOG(3) << "Splitting after cycle " << cycle;
58	
59	  // The nodes which need to be partitioned are those which can be scheduled in
60	  // either 'cycle' or 'cycle + 1'.
61	  std::vector<Node*> partitionable_nodes;
62	  for (Node* node : f->nodes()) {
63	    if (bounds->lb(node) <= cycle && bounds->ub(node) >= cycle + 1) {
64	      partitionable_nodes.push_back(node);
65	    }
66	  }
67	
68	  std::pair<std::vector<Node*>, std::vector<Node*>> partitions =
69	      sched::MinCostFunctionPartition(f, partitionable_nodes);
70	
71	  // Tighten bounds based on the cut.
72	  for (Node* node : partitions.first) {
73	    XLS_RETURN_IF_ERROR(bounds->TightenNodeUb(node, cycle));
74	  }
75	  for (Node* node : partitions.second) {
76	    XLS_RETURN_IF_ERROR(bounds->TightenNodeLb(node, cycle + 1));
77	  }
78	
79	  return absl::OkStatus();
80	}
81	
82	// Returns the number of pipeline registers (flops) on the interior of the
83	// pipeline not counting the input and output flops (if any).
84	absl::StatusOr<int64_t> CountInteriorPipelineRegisters(
85	    FunctionBase* f, const sched::ScheduleBounds& bounds) {
86	  int64_t registers = 0;
87	  for (Node* node : f->nodes()) {
88	    XLS_RET_CHECK_EQ(bounds.lb(node), bounds.ub(node)) << absl::StrFormat(
89	        "%s [%d, %d]", node->GetName(), bounds.lb(node), bounds.ub(node));
90	    int64_t latest_use = bounds.lb(node);
91	    for (Node* user : node->users()) {
92	      latest_use = std::max(latest_use, bounds.lb(user));
93	    }
94	    registers +=
95	        node->GetType()->GetFlatBitCount() * (latest_use - bounds.lb(node));
96	  }
97	  return registers;
98	}
99	
100	// Returns a sequence of numbers from first to last where the zeroth element of
101	// the sequence is the middle element between first and last. Subsequent
102	// elements are selected recursively out of the two intervals before and after
103	// the middle element.
104	std::vector<int64_t> MiddleFirstOrder(int64_t first, int64_t last) {
105	  if (first == last) {
106	    return {first};
107	  }
108	  if (first == last - 1) {
109	    return {first, last};
110	  }
111	
112	  int64_t middle = (first + last) / 2;
113	  std::vector<int64_t> head = MiddleFirstOrder(first, middle - 1);
114	  std::vector<int64_t> tail = MiddleFirstOrder(middle + 1, last);
115	
116	  std::vector<int64_t> ret;
117	  ret.push_back(middle);
118	  ret.insert(ret.end(), head.begin(), head.end());
119	  ret.insert(ret.end(), tail.begin(), tail.end());
120	  return ret;
121	}
122	
123	absl::StatusOr<ScheduleCycleMap> RunMinCutScheduler(
124	    FunctionBase* f, int64_t pipeline_stages, int64_t clock_period_ps,
125	    const DelayEstimator& delay_estimator, sched::ScheduleBounds* bounds,
126	    absl::Span<const SchedulingConstraint> constraints) {
127	  VLOG(3) << "MinCutScheduler()";
128	  VLOG(3) << "  pipeline stages = " << pipeline_stages;
129	  XLS_VLOG_LINES(4, f->DumpIr());
130	
131	  VLOG(4) << "Initial bounds:";
132	  XLS_VLOG_LINES(4, bounds->ToString());
133	
134	  for (const SchedulingConstraint& constraint : constraints) {
135	    if (std::holds_alternative<RecvsFirstSendsLastConstraint>(constraint)) {
136	      for (Node* node : f->nodes()) {
137	        if (node->Is<Receive>()) {
138	          XLS_RETURN_IF_ERROR(bounds->TightenNodeUb(node, 0));
139	        }
140	        if (node->Is<Send>()) {
141	          XLS_RETURN_IF_ERROR(bounds->TightenNodeLb(node, pipeline_stages - 1));
142	        }
143	      }
144	    } else {
145	      return absl::InternalError(
146	          "MinCutScheduler doesn't support constraints "
147	          "other than receives-first-sends-last.");
148	    }
149	  }
150	  XLS_RETURN_IF_ERROR(bounds->PropagateBounds());
151	
152	  for (Node* node : f->nodes()) {
153	    if (node->Is<MinDelay>()) {
154	      return absl::InternalError(
155	          "MinCutScheduler doesn't support min_delay nodes.");
156	    }
157	  }
158	
159	  // The state backedge must be in the first cycle.
160	  if (Proc* proc = dynamic_cast<Proc*>(f)) {
161	    for (Node* node : proc->params()) {
162	      XLS_RETURN_IF_ERROR(bounds->TightenNodeUb(node, 0));
163	    }
164	    for (Node* node : proc->next_values()) {
165	      XLS_RETURN_IF_ERROR(bounds->TightenNodeUb(node, 0));
166	    }
167	  }
168	  XLS_RETURN_IF_ERROR(bounds->PropagateBounds());
169	
170	  // Try a number of different orderings of cycle boundary at which the min-cut
171	  // is performed and keep the best one.
172	  int64_t best_register_count = std::numeric_limits<int64_t>::max();
173	  std::optional<sched::ScheduleBounds> best_bounds;
174	  for (const std::vector<int64_t>& cut_order :
175	       GetMinCutCycleOrders(pipeline_stages - 1)) {
176	    VLOG(3) << absl::StreamFormat("Trying cycle order: {%s}",
177	                                  absl::StrJoin(cut_order, ", "));
178	    sched::ScheduleBounds trial_bounds = *bounds;
179	    // Partition the nodes at each cycle boundary. For each iteration, this
180	    // splits the nodes into those which must be scheduled at or before the
181	    // cycle and those which must be scheduled after. Upon loop completion each
182	    // node will have a range of exactly one cycle.
183	    for (int64_t cycle : cut_order) {
184	      XLS_RETURN_IF_ERROR(
185	          SplitAfterCycle(f, cycle, delay_estimator, &trial_bounds));
186	      XLS_RETURN_IF_ERROR(trial_bounds.PropagateBounds());
187	    }
188	    XLS_ASSIGN_OR_RETURN(int64_t trial_register_count,
189	                         CountInteriorPipelineRegisters(f, trial_bounds));
190	    if (!best_bounds.has_value() ||
191	        best_register_count > trial_register_count) {
192	      best_bounds = std::move(trial_bounds);
193	      best_register_count = trial_register_count;
194	    }
195	  }
196	  *bounds = std::move(*best_bounds);
197	
198	  ScheduleCycleMap cycle_map;
199	  for (Node* node : f->nodes()) {
200	    XLS_RET_CHECK_EQ(bounds->lb(node), bounds->ub(node)) << node->GetName();
201	    cycle_map[node] = bounds->lb(node);
202	  }
203	  return cycle_map;
204	}
205	}  // namespace
206	
207	std::vector<std::vector<int64_t>> GetMinCutCycleOrders(int64_t length) {
208	  if (length == 0) {
209	    return {{}};
210	  }
211	  if (length == 1) {
212	    return {{0}};
213	  }
214	  if (length == 2) {
215	    return {{0, 1}, {1, 0}};
216	  }
217	  // For lengths greater than 2, return forward, reverse and middle first
218	  // orderings.
219	  std::vector<std::vector<int64_t>> orders;
220	  std::vector<int64_t> forward(length);
221	  std::iota(forward.begin(), forward.end(), 0);
222	  orders.push_back(forward);
223	
224	  std::vector<int64_t> reverse(length);
225	  std::iota(reverse.begin(), reverse.end(), 0);
226	  std::reverse(reverse.begin(), reverse.end());
227	  orders.push_back(reverse);
228	
229	  orders.push_back(MiddleFirstOrder(0, length - 1));
230	  return orders;
231	}
232	
233	absl::StatusOr<ScheduleCycleMap> MinCutScheduler::Schedule(
234	    std::optional<int64_t> pipeline_stages, int64_t clock_period_ps,
235	    SchedulingFailureBehavior failure_behavior,
236	    std::optional<int64_t> worst_case_throughput) {
237	  XLS_ASSIGN_OR_RETURN(
238	      sched::ScheduleBounds bounds,
239	      ComputeBounds(pipeline_stages, clock_period_ps, worst_case_throughput));
240	  XLS_RET_CHECK(std::holds_alternative<FunctionBase*>(graph().ir_scope()));
241	  XLS_RET_CHECK(pipeline_stages.has_value())
242	      << "Min cut does not support unspecified pipeline stages.";
243	  auto* f = std::get<FunctionBase*>(graph().ir_scope());
244	  return RunMinCutScheduler(f, pipeline_stages.value(), clock_period_ps,
245	                            delay_estimator(), &bounds, constraints());
246	}
247	
