79	// Tighten `bounds` to the ASAP/ALAP bounds for each node. If `schedule_length`
80	// is given, then the ALAP bounds are computed with the given length. Otherwise,
81	// we use the minimum viable pipeline length, per the ASAP bounds.
82	//
83	// Both schedules will be feasible if no other scheduling constraints are
84	// applied.
85	absl::Status TightenBounds(sched::ScheduleBounds& bounds, FunctionBase* f,
86	                           std::optional<int64_t> schedule_length) {
87	  // If we have a schedule length give everything that upper bound.
88	  if (schedule_length.has_value()) {
89	    for (Node* node : f->nodes()) {
90	      XLS_RETURN_IF_ERROR(
91	          bounds.TightenNodeUb(node, schedule_length.value() - 1));
92	    }
93	  }
94	  // If we have a schedule_length (and therefore a small-ish max stage) we can
95	  // try to propagate forever since we will hit that schedule length before
96	  // long.
97	  std::optional<int64_t> propagation_fuel =
98	      schedule_length ? std::nullopt : std::make_optional<int64_t>(6);
99	  XLS_RETURN_IF_ERROR(bounds.PropagateBounds(propagation_fuel))
100	      << "Failed to schedule bounds for " << f->name() << ".";
101	  return absl::OkStatus();
102	}
103	
104	// Returns the critical path through the given nodes (ordered topologically),
105	// ignoring nodes that will be dead after synthesis.
106	absl::StatusOr<int64_t> ComputeCriticalPath(
107	    const ScheduleGraph& graph, const DelayEstimator& delay_estimator) {
108	  int64_t function_cp = 0;
109	  absl::flat_hash_map<Node*, int64_t> node_cp;
110	  for (const auto& sn : graph.nodes()) {
111	    if (sn.is_dead_after_synthesis) {
112	      continue;
113	    }
114	    int64_t node_start = 0;
115	    for (Node* operand : sn.node->operands()) {
116	      node_start = std::max(node_start, node_cp[operand]);
117	    }
118	    XLS_ASSIGN_OR_RETURN(int64_t node_delay,
119	                         delay_estimator.GetOperationDelayInPs(sn.node));
120	    node_cp[sn.node] = node_start + node_delay;
121	    function_cp = std::max(function_cp, node_cp[sn.node]);
122	  }
123	  return function_cp;
124	}
125	
126	// Returns the minimum clock period in picoseconds for which it is feasible to
127	// schedule the function into a pipeline with the given number of stages. If
128	// `target_clock_period_ps` is specified, will not try to check lower clock
129	// periods than this.
130	absl::StatusOr<int64_t> FindMinimumClockPeriod(
131	    const ScheduleGraph& graph, std::optional<int64_t> pipeline_stages,
132	    std::optional<int64_t> worst_case_throughput,
133	    const DelayEstimator& delay_estimator, Scheduler& scheduler,
134	    SchedulingFailureBehavior failure_behavior,
135	    std::optional<int64_t> target_clock_period_ps = std::nullopt) {
136	  VLOG(4) << "FindMinimumClockPeriod()";
137	  VLOG(4) << "  graph = " << graph.name();
138	  VLOG(4) << "  scheduler = " << scheduler.name();
139	  VLOG(4) << "  pipeline stages = "
140	          << (pipeline_stages.has_value() ? absl::StrCat(*pipeline_stages)
141	                                          : "(unspecified)");
142	  VLOG(4) << "  worst case throughput = "
143	          << (worst_case_throughput.has_value()
144	                  ? absl::StrCat(*worst_case_throughput)
145	                  : "(unspecified)");
146	  VLOG(4) << "  target clock period = "
147	          << (target_clock_period_ps.has_value()
148	                  ? absl::StrCat(*target_clock_period_ps)
149	                  : "(unspecified)");
150	  XLS_ASSIGN_OR_RETURN(int64_t function_cp_ps,
151	                       ComputeCriticalPath(graph, delay_estimator));
152	
153	  // The upper bound of the search is simply the critical path of the entire
154	  // function, and the lower bound is the critical path delay evenly distributed
155	  // across our pipeline stages (rounded up). It's possible the upper bound is
156	  // the best you can do if there exists a single operation with delay equal to
157	  // the critical-path delay of the function.
158	  int64_t pessimistic_clk_period_ps = std::max(int64_t{1}, function_cp_ps);
159	  int64_t optimistic_clk_period_ps = 1;
160	  if (pipeline_stages.has_value()) {
161	    optimistic_clk_period_ps =
162	        std::max(optimistic_clk_period_ps,
163	                 CeilOfRatio(function_cp_ps, *pipeline_stages));
164	  }
165	  if (target_clock_period_ps.has_value()) {
166	    // Don't check any clock period less than the specified target.
167	    optimistic_clk_period_ps =
168	        std::max(optimistic_clk_period_ps, *target_clock_period_ps);
169	    pessimistic_clk_period_ps =
170	        std::max(pessimistic_clk_period_ps, *target_clock_period_ps);
171	  }
172	  VLOG(4) << absl::StreamFormat("Binary searching over interval [%d, %d]",
173	                                optimistic_clk_period_ps,
174	                                pessimistic_clk_period_ps);
175	
176	  // Check that it is in fact possible to
177	  // schedule this function at all; if not, return a useful error.
178	  XLS_RETURN_IF_ERROR(scheduler
179	                          .Schedule(pipeline_stages, pessimistic_clk_period_ps,
180	                                    failure_behavior, worst_case_throughput)
181	                          .status())
182	          .SetPrepend()
183	      << absl::StrFormat(
184	             "Impossible to schedule %s %s as specified with clock period %d",
185	             (graph.IsSingleProc() ? "proc" : "function"), graph.name(),
186	             pessimistic_clk_period_ps);
187	
188	  // Don't waste time explaining infeasibility for the failing points in the
189	  // search.
190	  failure_behavior.explain_infeasibility = false;
191	  int64_t min_clk_period_ps = BinarySearchMinTrue(
192	      optimistic_clk_period_ps, pessimistic_clk_period_ps,
193	      [&](int64_t clk_period_ps) {
194	        auto sched =
195	            scheduler.Schedule(pipeline_stages, clk_period_ps, failure_behavior,
196	                               worst_case_throughput);
197	        VLOG(4) << "FindMinClockPeriod(" << graph.name()
198	                << ", pipeline_stages=" << pipeline_stages.value_or(-1)
199	                << ", worst_case_throughput="
200	                << worst_case_throughput.value_or(-1)
201	                << ", clk_period_ps=" << clk_period_ps
202	                << "): " << sched.status();
203	        return sched.ok();
204	      },
205	      BinarySearchAssumptions::kEndKnownTrue);
206	  VLOG(4) << "minimum clock period = " << min_clk_period_ps;
207	
208	  return min_clk_period_ps;
209	}
