211	// Returns the minimum inverse worst-case throughput for which it is feasible to
212	// schedule the function into a pipeline with the given number of stages and
213	// target clock period.
214	absl::StatusOr<int64_t> FindMinimumWorstCaseThroughput(
215	    Proc* proc, std::optional<int64_t> pipeline_stages, int64_t clock_period_ps,
216	    Scheduler& scheduler, SchedulingFailureBehavior failure_behavior) {
217	  VLOG(4) << "FindMinimumWorstCaseThroughput()";
218	  VLOG(4) << "  pipeline stages = "
219	          << (pipeline_stages.has_value() ? absl::StrCat(*pipeline_stages)
220	                                          : "(unspecified)")
221	          << ", clock period = " << clock_period_ps << " ps";
222	
223	  // Check that it is in fact possible to schedule this function at all, with no
224	  // worst-case throughput bound; if not, return a useful error.
225	  XLS_ASSIGN_OR_RETURN(
226	      ScheduleCycleMap schedule_cycle_map,
227	      scheduler.Schedule(pipeline_stages, clock_period_ps, failure_behavior,
228	                         /*worst_case_throughput=*/std::nullopt),
229	      _.SetPrepend() << absl::StrFormat(
230	          "Impossible to schedule proc %s as specified; proc ", proc->name()));
231	
232	  // Extract the worst-case throughput from this schedule as an upper bound.
233	  int64_t pessimistic_worst_case_throughput = 1;
234	  for (Next* next : proc->next_values()) {
235	    Node* state_read = proc->GetStateReadByStateElement(next->state_element());
236	    const int64_t backedge_length =
237	        schedule_cycle_map[next] - schedule_cycle_map[state_read];
238	    pessimistic_worst_case_throughput =
239	        std::max(pessimistic_worst_case_throughput, backedge_length + 1);
240	  }
241	  VLOG(4) << absl::StreamFormat(
242	      "Schedules at worst-case throughput %d; now binary searching over "
243	      "interval [1, %d]",
244	      pessimistic_worst_case_throughput, pessimistic_worst_case_throughput);
245	
246	  // Don't waste time explaining infeasibility for the failing points in the
247	  // search.
248	  failure_behavior.explain_infeasibility = false;
249	  int64_t min_worst_case_throughput = BinarySearchMinTrue(
250	      1, pessimistic_worst_case_throughput,
251	      [&](int64_t worst_case_throughput) {
252	        CHECK(!failure_behavior.explain_infeasibility);
253	        auto sched = scheduler.Schedule(
254	            pipeline_stages, clock_period_ps, failure_behavior,
255	            /*worst_case_throughput=*/worst_case_throughput);
256	        VLOG(4) << "FindMinimumWorstCaseThroughput("
257	                << absl::StreamFormat(
258	                       "pipeline_stages=%d, clock_period_ps=%d, "
259	                       "worst_case_throughput=%d",
260	                       pipeline_stages.value_or(-1), clock_period_ps,
261	                       worst_case_throughput)
262	                << "): " << sched.status();
263	        sched.IgnoreError();
264	        return sched.ok();
265	      },
266	      BinarySearchAssumptions::kEndKnownTrue);
267	  VLOG(4) << "minimum worst-case throughput = " << min_worst_case_throughput;
268	
269	  return min_worst_case_throughput;
270	}
