272	// Returns true if the given node communicates via a channel which is on the
273	// interface of the top-level proc.
274	// TODO(meheff): Revisit whether this is the right thing to do.  This will
275	// return true if any instance of the proc has the channel as an I/O. With
276	// multiple instantiations, this could lead to unexpected behavior.
277	bool IsExternalIoNode(ChannelNode* node,
278	                      const std::optional<const ProcElaboration*> elab) {
279	  Proc* proc = node->function_base()->AsProcOrDie();
280	  if (proc->is_new_style_proc()) {
281	    // Channels are proc-scoped.
282	    absl::StatusOr<ChannelInterface*> channel_interface =
283	        proc->GetChannelInterface(node->As<ChannelNode>()->channel_name(),
284	                                  node->Is<Send>()
285	                                      ? ChannelDirection::kSend
286	                                      : ChannelDirection::kReceive);
287	    CHECK_OK(channel_interface.status());
288	    CHECK(elab.has_value());
289	    for (ChannelInstance* channel_instance :
290	         (*elab)->GetInstancesOfChannelInterface(channel_interface.value())) {
291	      if ((*elab)->IsTopInterfaceChannel(channel_instance)) {
292	        return true;
293	      }
294	    }
295	    return false;
296	  }
297	
298	  // Channels are globally scoped.
299	  absl::StatusOr<Channel*> chan = GetChannelUsedByNode(node);
300	  CHECK_OK(chan.status());
301	  return (*chan)->supported_ops() != ChannelOps::kSendReceive;
302	}
