304	absl::StatusOr<int64_t> ApplyClockMargin(const SchedulingOptions& options,
305	                                         int64_t clock_period_ps) {
306	  if (!options.clock_margin_percent().has_value()) {
307	    return clock_period_ps;
308	  }
309	
310	  int64_t original_clock_period_ps = clock_period_ps;
311	  clock_period_ps -=
312	      (clock_period_ps * *options.clock_margin_percent() + 50) / 100;
313	  if (clock_period_ps <= 0) {
314	    return absl::InvalidArgumentError(absl::StrFormat(
315	        "Clock period non-positive (%dps) after adjusting for margin. "
316	        "Original clock period: %dps, clock margin: %d%%",
317	        clock_period_ps, original_clock_period_ps,
318	        *options.clock_margin_percent()));
319	  }
320	  return clock_period_ps;
321	}
