323	// Handles the case where scheduling fails, providing more informative error
324	// messages based on the failure type and options.
325	absl::Status HandleScheduleFailure(
326	    absl::Status schedule_status, const ScheduleGraph& graph,
327	    const SchedulingOptions& options,
328	    std::optional<int64_t> worst_case_throughput,
329	    const DelayEstimator& io_delay_added,
330	    std::optional<int64_t>& min_clock_period_ps_for_tracing,
331	    int64_t clock_period_ps, Scheduler& bounds_scheduler) {
332	  if (absl::IsInvalidArgument(schedule_status)) {
333	    // The scheduler was able to explain the failure; report it up without
334	    // further analysis.
335	    return schedule_status;
336	  }
337	  if (options.clock_period_ps().has_value()) {
338	    // The user specified a specific clock period; see if we can confirm
339	    // that that's the issue.
340	
341	    if (options.minimize_clock_on_failure().value_or(true)) {
342	      // Find the smallest clock period that would have worked.
343	      LOG(LEVEL(options.recover_after_minimizing_clock().value_or(false)
344	                    ? absl::LogSeverity::kWarning
345	                    : absl::LogSeverity::kError))
346	          << "Unable to schedule with the specified clock period ("
347	          << clock_period_ps
348	          << " ps); finding the shortest feasible clock period...";
349	      int64_t target_clock_period_ps = clock_period_ps + 1;
350	      absl::StatusOr<int64_t> min_clock_period_ps = FindMinimumClockPeriod(
351	          graph, options.pipeline_stages(), worst_case_throughput,
352	          io_delay_added, bounds_scheduler, options.failure_behavior(),
353	          target_clock_period_ps);
354	      VLOG(4) << "FindMinimumClockPeriod() returned " << min_clock_period_ps;
355	      if (min_clock_period_ps.ok()) {
356	        min_clock_period_ps_for_tracing = *min_clock_period_ps;
357	        // Just increasing the clock period suffices.
358	        return absl::InvalidArgumentError(
359	            absl::StrFormat("cannot achieve the specified clock period. Try "
360	                            "`--clock_period_ps=%d`.",
361	                            *min_clock_period_ps));
362	      }
363	      if (absl::IsInvalidArgument(min_clock_period_ps.status())) {
364	        // We failed with an explained error at the longest possible clock
365	        // period. Report this error up, adding that the clock period will
366	        // also need to be increased - though we don't know by how much.
367	        return absl::StatusBuilder(std::move(min_clock_period_ps).status())
368	                   .SetPrepend()
369	               << absl::StrFormat(
370	                      "cannot achieve the specified clock period; try "
371	                      "increasing `--clock_period_ps`. Also, ");
372	      }
373	      // We fail with an unexplained error even at the longest possible
374	      // clock period. Report the original error.
375	      return schedule_status;
376	    }
377	
378	    // Check if just increasing the clock period would have helped.
379	    XLS_ASSIGN_OR_RETURN(int64_t pessimistic_clock_period_ps,
380	                         ComputeCriticalPath(graph, io_delay_added));
381	    // Make a copy of failure behavior with explain_feasibility true- we
382	    // always want to produce an error message because this we are
383	    // re-running the scheduler for its error message.
384	    SchedulingFailureBehavior pessimistic_failure_behavior =
385	        options.failure_behavior();
386	    pessimistic_failure_behavior.explain_infeasibility = true;
387	    absl::Status pessimistic_status =
388	        bounds_scheduler
389	            .Schedule(options.pipeline_stages(), pessimistic_clock_period_ps,
390	                      pessimistic_failure_behavior)
391	            .status();
392	    if (pessimistic_status.ok()) {
393	      // Just increasing the clock period suffices.
394	      return absl::InvalidArgumentError(
395	          "cannot achieve the specified clock period. Try increasing "
396	          "`--clock_period_ps`.");
397	    }
398	    if (absl::IsInvalidArgument(pessimistic_status)) {
399	      // We failed with an explained error at the pessimistic clock period.
400	      // Report this error up, adding that the clock period will also need
401	      // to be increased - though we don't know by how much.
402	      return absl::StatusBuilder(std::move(pessimistic_status)).SetPrepend()
403	             << absl::StrFormat(
404	                    "cannot achieve the specified clock period; try "
405	                    "increasing `--clock_period_ps`. Also, ");
406	    }
407	    return pessimistic_status;
408	  }
409	  return schedule_status;
410	}
