412	absl::StatusOr<PipelineSchedule> RunIterativeSDCSchedule(
413	    FunctionBase* f, const SchedulingOptions& options, int64_t clock_period_ps,
414	    const DelayEstimator& delay_estimator,
415	    const synthesis::Synthesizer* synthesizer) {
416	  if (!options.clock_period_ps().has_value()) {
417	    return absl::UnimplementedError(
418	        "Iterative SDC scheduling is only supported when a clock period is "
419	        "specified.");
420	  }
421	
422	  IterativeSDCSchedulingOptions isdc_options;
423	  isdc_options.synthesizer = synthesizer;
424	  isdc_options.iteration_number = options.fdo_iteration_number();
425	  isdc_options.delay_driven_path_number =
426	      options.fdo_delay_driven_path_number();
427	  isdc_options.fanout_driven_path_number =
428	      options.fdo_fanout_driven_path_number();
429	  isdc_options.stochastic_ratio = options.fdo_refinement_stochastic_ratio();
430	  isdc_options.path_evaluate_strategy = options.fdo_path_evaluate_strategy();
431	
432	  XLS_ASSIGN_OR_RETURN(DelayManager delay_manager,
433	                       DelayManager::Create(f, delay_estimator));
434	  XLS_ASSIGN_OR_RETURN(
435	      ScheduleCycleMap cycle_map,
436	      ScheduleByIterativeSDC(f, options.pipeline_stages(), clock_period_ps,
437	                             delay_manager, options.constraints(), isdc_options,
438	                             options.failure_behavior()));
439	
440	  // Use delay manager for scheduling timing verification.
441	  XLS_ASSIGN_OR_RETURN(
442	      PipelineSchedule schedule,
443	      PipelineSchedule::Create(f, cycle_map,
444	                               {.length = options.pipeline_stages()}));
445	  XLS_RETURN_IF_ERROR(schedule.Verify());
446	  XLS_RETURN_IF_ERROR(schedule.VerifyTiming(clock_period_ps, delay_manager));
447	  XLS_RETURN_IF_ERROR(
448	      schedule.VerifyConstraints(options.constraints(), options));
449	
450	  XLS_VLOG_LINES(3, "Schedule\n" + schedule.ToString());
451	  return schedule;
452	}
