454	// NB For backwards compatibility reasons the flag options for worst case
455	// throughput/II are rather confusing. Specifically, a value of 0 means that
456	// the scheduler is free to choose any WCT it wants and a value of nullopt
457	// means the value must be exactly 1.
458	//
459	// To make everything after this clearer we change this interpretation to have
460	// std::nullopt mean "no throughput requirements" and `Some(X)` mean a
461	// throughput requirement of X. Therefore a value of 0 from now on is invalid.
462	std::optional<int64_t> GetWorstCaseThroughputSetting(
463	    const SchedulingOptions& options, FunctionBase* f) {
464	  if (!f->IsProc()) {
465	    VLOG(4) << "No II is possible because this is not a proc.";
466	    return std::nullopt;
467	  }
468	  std::optional<int64_t> worst_case_throughput =
469	      options.worst_case_throughput();
470	  if (worst_case_throughput && *worst_case_throughput == 0) {
471	    VLOG(4) << "Setting II to unconstrained from options.";
472	    worst_case_throughput = std::nullopt;
473	  } else if (!worst_case_throughput) {
474	    // No throughput requirement from options, See if the proc has one.
475	    //
476	    // NB This is only reachable if the scheduler is being configured from
477	    // something other than scheduling_options_flags.cc and has complicated
478	    // backwards-compat behaviors.
479	    //
480	    // In the future we are likely to move towards this being the primary way of
481	    // configuring things however and we may want to reconsider how it is
482	    // interpreted if/when that happens.
483	    //
484	    // TODO(allight): It may be worthwhile to go through and figure out what
485	    // tests/other tools depend on this behavior to rationalize it all.
486	    if (f->IsProc() && f->GetInitiationInterval()) {
487	      // Now convert this to the new interpretation.
488	      worst_case_throughput = f->GetInitiationInterval();
489	      if (worst_case_throughput == 0) {
490	        VLOG(4) << "Setting II to unconstrained from proc setting.";
491	        worst_case_throughput = std::nullopt;
492	      } else {
493	        VLOG(4) << "Setting II to " << *worst_case_throughput
494	                << " from proc setting.";
495	      }
496	    } else if (options.minimize_worst_case_throughput()) {
497	      VLOG(4) << "Setting II to unconstrained since no options or proc setting "
498	                 "and MinimizeWorstCaseThroughput is true.";
499	      worst_case_throughput = std::nullopt;
500	    } else {
501	      if (!options.arc_worst_case_throughput().empty() ||
502	          options.default_arc_worst_case_throughput().has_value()) {
503	        VLOG(4) << "Setting II to unconstrained since custom arc throughput "
504	                   "options are present and worst_case_throughput is "
505	                   "unspecified.";
506	        worst_case_throughput = std::nullopt;
507	      } else {
508	        VLOG(4) << "Setting II to 1 since no options or proc setting and "
509	                   "MinimizeWorstCaseThroughput is false.";
510	        worst_case_throughput = 1;
511	      }
512	    }
513	  } else {
514	    VLOG(4) << "Setting II to " << *worst_case_throughput
515	            << " from worst_case_throughput option.";
516	  }
517	  return worst_case_throughput;
518	}
519	
520	// Set the WCT (either calculated or from options) to the function. For
521	// compatibility we need this to be in the same strange format as the option
522	// setting. Specifically where nullopt means a WCT of 1, and a value of 0 means
523	// unconstrained and all other values are WCT of the value.
524	//
525	// TODO(allight): Go through and update all users to the internal format where
526	// std::nullopt means unconstrained and any value is an exact WCT.
527	void SetWorstCaseThroughput(std::optional<int64_t> worst_case_throughput,
528	                            FunctionBase* f) {
529	  if (!f->IsProc()) {
530	    return;
531	  }
532	  if (worst_case_throughput.has_value()) {
533	    if (worst_case_throughput == 1) {
534	      f->AsProcOrDie()->ClearInitiationInterval();
535	    } else {
536	      f->AsProcOrDie()->SetInitiationInterval(*worst_case_throughput);
537	    }
538	  } else {
539	    f->AsProcOrDie()->SetInitiationInterval(0);
540	  }
541	}
