543	absl::StatusOr<PipelineSchedule> RunPipelineScheduleInternal(
544	    FunctionBase* f, const DelayEstimator& delay_estimator,
545	    const SchedulingOptions& options,
546	    const std::optional<const ProcElaboration*> elab,
547	    const synthesis::Synthesizer* synthesizer) {
548	  if (!options.pipeline_stages().has_value() &&
549	      !options.clock_period_ps().has_value()) {
550	    return absl::InvalidArgumentError(
551	        "Pipeline scheduling requires either --pipeline_stages or "
552	        "--clock_period_ps to be specified; see "
553	        "https://google.github.io/xls/codegen_options/"
554	        "#pipelining-and-scheduling-options for details.");
555	  }
556	
557	  if (f->IsProc() && f->AsProcOrDie()->is_new_style_proc() &&
558	      !elab.has_value()) {
559	    return absl::InvalidArgumentError(
560	        "Pipeline scheduling of a proc with proc-scoped channels requires an "
561	        "elaboration.");
562	  }
563	
564	  XLS_RETURN_IF_ERROR(
565	      VerifyArcWorstCaseThroughputViability(f->package(), options));
566	
567	  // NB For backwards compatibility reasons the flag options for worst case
568	  // throughput/II are rather confusing. Specifically, a value of 0 means that
569	  // the scheduler is free to choose any WCT it wants and a value of nullopt
570	  // means the value must be exactly 1.
571	  //
572	  // To make everything after this clearer we change this interpretation to have
573	  // std::nullopt mean "no throughput requirements" and `Some(X)` mean a
574	  // throughput requirement of X. Therefore a value of 0 from now on is invalid.
575	  std::optional<int64_t> worst_case_throughput =
576	      GetWorstCaseThroughputSetting(options, f);
577	
578	  VLOG(4) << "Computed WCT is "
579	          << (worst_case_throughput.has_value()
580	                  ? absl::StrCat(*worst_case_throughput)
581	                  : "unconstrained");
582	
583	  int64_t input_delay = options.additional_input_delay_ps().value_or(0);
584	  int64_t output_delay = options.additional_output_delay_ps().value_or(0);
585	  // Sends and receives each have inputs and outputs from the flow control
586	  // signals, so the max of input and output delays is the amount needed for
587	  // each channel.
588	  int64_t max_io_delay = std::max(input_delay, output_delay);
589	
590	  DecoratingDelayEstimator io_delay_added(
591	      "io_delay_added", delay_estimator, [&](Node* node, int64_t base_delay) {
592	        if (node->Is<ChannelNode>()) {
593	          std::string_view channel_name =
594	              node->As<ChannelNode>()->channel_name();
595	          std::string channel_op = absl::StrCat(
596	              channel_name, ":",
597	              node->As<ChannelNode>()->direction() == ChannelDirection::kSend
598	                  ? "send"
599	                  : "recv");
600	          int64_t channel_delay_ps = 0;
601	          if (std::optional<int64_t> op_delay =
602	                  options.additional_channel_delay_ps(channel_op);
603	              op_delay.has_value()) {
604	            channel_delay_ps = *op_delay;
605	          } else if (std::optional<int64_t> channel_delay =
606	                         options.additional_channel_delay_ps(channel_name);
607	                     channel_delay.has_value()) {
608	            channel_delay_ps = *channel_delay;
609	          }
610	
611	          if (IsExternalIoNode(node->As<ChannelNode>(), elab)) {
612	            return base_delay + max_io_delay + channel_delay_ps;
613	          }
614	
615	          return base_delay + channel_delay_ps;
616	        }
617	        if (node->function_base()->IsFunction()) {
618	          if (node->Is<Param>()) {
619	            return base_delay + input_delay;
620	          }
621	          if (node->function_base()->AsFunctionOrDie()->return_value() ==
622	              node) {
623	            return base_delay + output_delay;
624	          }
625	        }
626	        return base_delay;
627	      });
628	
629	  if (worst_case_throughput == 0) {
630	    VLOG(4) << "Worst case throughput explicitly set to 0 (unbounded).";
631	    worst_case_throughput = std::nullopt;
632	  }
633	
634	  if (options.pipeline_stages() == 1 &&
635	      !options.clock_period_ps().has_value()) {
636	    // No scheduling to be done, and there's no way to violate timing; just
637	    // schedule everything timed into the first cycle.
638	    ScheduleCycleMap cycle_map;
639	    XLS_ASSIGN_OR_RETURN(std::vector<Node*> topo_sort_nodes, TopoSort(f));
640	    for (Node* node : topo_sort_nodes) {
641	      if (!IsUntimed(node)) {
642	        cycle_map[node] = 0;
643	      }
644	    }
645	    XLS_ASSIGN_OR_RETURN(absl::flat_hash_set<Node*> dead_after_synthesis,
646	                         GetDeadAfterSynthesisNodes(f));
647	    XLS_ASSIGN_OR_RETURN(ScheduleGraph graph,
648	                         ScheduleGraph::Create(f, dead_after_synthesis));
649	    XLS_ASSIGN_OR_RETURN(int64_t min_clock_period_ps,
650	                         ComputeCriticalPath(graph, io_delay_added));
651	    XLS_ASSIGN_OR_RETURN(
652	        PipelineSchedule schedule,
653	        PipelineSchedule::Create(f, std::move(cycle_map),
654	                                 {.length = options.pipeline_stages(),
655	                                  .min_clock_period_ps = std::max(
656	                                      int64_t{1}, min_clock_period_ps)}));
657	    absl::Status status = schedule.Verify();
658	    status.Update(schedule.VerifyConstraints(options.constraints(), options));
659	    if (status.ok()) {
660	      XLS_VLOG_LINES(3, "Schedule\n" + schedule.ToString());
661	      return schedule;
662	    }
663	
664	    // If we don't need to explain the infeasibility, return the error.
665	    if (!options.failure_behavior().explain_infeasibility) {
666	      return std::move(status);
667	    }
668	
669	    // If we do need to explain the infeasibility, fall through to the normal
670	    // scheduling code to let it attempt to explain.
671	  }
672	
673	  XLS_ASSIGN_OR_RETURN(absl::flat_hash_set<Node*> dead_after_synthesis,
674	                       GetDeadAfterSynthesisNodes(f));
675	  XLS_ASSIGN_OR_RETURN(ScheduleGraph graph,
676	                       ScheduleGraph::Create(f, dead_after_synthesis));
677	
678	  // std::unique_ptr<SDCScheduler> sdc_scheduler;
679	  std::unique_ptr<Scheduler> scheduler;
680	  auto create_scheduler =
681	      [&](SchedulingStrategy strategy,
682	          std::optional<double> dynamic_throughput_objective_weight,
683	          bool check_feasibility)
684	      -> absl::StatusOr<std::unique_ptr<Scheduler>> {
685	    std::unique_ptr<Scheduler> s;
686	    switch (strategy) {
687	      case SchedulingStrategy::ASAP: {
688	        s = std::make_unique<ASAPScheduler>(graph, io_delay_added);
689	        break;
690	      }
691	      case SchedulingStrategy::MIN_CUT: {
692	        s = std::make_unique<MinCutScheduler>(graph, io_delay_added);
693	        break;
694	      }
695	      case SchedulingStrategy::SDC: {
696	        XLS_ASSIGN_OR_RETURN(
697	            std::unique_ptr<SDCScheduler> sdc_scheduler,
698	            SDCScheduler::Create(graph, io_delay_added, options));
699	        sdc_scheduler->SetCheckFeasibility(check_feasibility);
700	        sdc_scheduler->SetDynamicThroughputObjectiveWeight(
701	            dynamic_throughput_objective_weight);
702	        s = std::move(sdc_scheduler);
703	        break;
704	      }
705	      case SchedulingStrategy::RANDOM: {
706	        s = std::make_unique<RandomScheduler>(
707	            graph, io_delay_added,
708	            absl::BitGen(std::seed_seq{options.seed().value_or(0)}));
709	        break;
710	      }
711	    }
712	    VLOG(4) << "Constraints are : ["
713	            << absl::StrJoin(options.constraints(), ",") << "]";
714	    XLS_RETURN_IF_ERROR(s->AddConstraints(options.constraints()));
715	    return std::move(s);
716	  };
717	  auto initialize_scheduler = [&]() -> absl::Status {
718	    if (scheduler == nullptr) {
719	      XLS_ASSIGN_OR_RETURN(
720	          scheduler,
721	          create_scheduler(options.strategy(),
722	                           options.dynamic_throughput_objective_weight(),
723	                           /*check_feasibility=*/false));
724	    }
725	    VLOG(4) << "Using scheduler " << scheduler->name()
726	            << " for primary scheduling.";
727	    return absl::OkStatus();
728	  };
729	  std::unique_ptr<Scheduler> bounds_scheduler;
730	  auto initialize_bounds_scheduler = [&]() -> absl::Status {
731	    if (bounds_scheduler == nullptr) {
732	      // Even if we are SDC we ignore the dynamic_throughput_objective_weight
733	      // for bounds.
734	      XLS_ASSIGN_OR_RETURN(
735	          bounds_scheduler,
736	          create_scheduler(options.find_bounds_strategy(),
737	                           /*dynamic_throughput_objective_weight=*/std::nullopt,
738	                           /*check_feasibility=*/true));
739	    }
740	    VLOG(4) << "Using scheduler " << bounds_scheduler->name() << " for bounds.";
741	    return absl::OkStatus();
742	  };
743	
744	  std::optional<int64_t> min_clock_period_ps_for_tracing;
745	  int64_t clock_period_ps;
746	  if (!options.clock_period_ps().has_value() ||
747	      (options.minimize_clock_on_failure().value_or(false) &&
748	       options.recover_after_minimizing_clock().value_or(false))) {
749	    // We don't know the exact target clock period - either none was provided,
750	    // or we want to fall back to the minimum feasible clock period if the
751	    // target is infeasible. Determine the minimum clock period for which the
752	    // function can be scheduled in the given pipeline length (adjusted for the
753	    // user-specified relaxation percent if needed), and use that if it's
754	    // smaller than the target clock period.
755	    //
756	    // TODO(allight): Ideally we'd always use the ASAP scheduler but it is
757	    // possible to create graphs that are not ASAP schedulable. For now just
758	    // use the configured bounds strategy.
759	    VLOG(4) << "Finding min clock due to "
760	            << (!options.clock_period_ps().has_value()
761	                    ? "no target clock period"
762	                    : "minimize_clock_on_failure and recover_after_minimizing_"
763	                      "clock");
764	    XLS_RETURN_IF_ERROR(initialize_bounds_scheduler());
765	    XLS_ASSIGN_OR_RETURN(
766	        min_clock_period_ps_for_tracing,
767	        FindMinimumClockPeriod(graph, options.pipeline_stages(),
768	                               worst_case_throughput, io_delay_added,
769	                               *bounds_scheduler, options.failure_behavior()));
770	
771	    // Pad the minimum clock period to account for the clock margin.
772	    if (options.clock_margin_percent().has_value()) {
773	      if (*options.clock_margin_percent() >= 100) {
774	        return absl::InvalidArgumentError(
775	            "Clock margin percent must be less than 100.");
776	      }
777	      *min_clock_period_ps_for_tracing =
778	          (*min_clock_period_ps_for_tracing * 100 + 50) /
779	          (100 - *options.clock_margin_percent());
780	    }
781	
782	    // Set the clock period to the minimum feasible value.
783	    clock_period_ps = *min_clock_period_ps_for_tracing;
784	
785	    if (options.period_relaxation_percent().has_value()) {
786	      // Apply the user-specified relaxation to allow less evenly distributed
787	      // slack.
788	      int64_t relaxation_percent = options.period_relaxation_percent().value();
789	      int64_t adjustment = ((clock_period_ps * relaxation_percent + 50) / 100);
790	      VLOG(4) << "Applying period relaxation of " << adjustment
791	              << " ps to clock period of " << clock_period_ps
792	              << " ps. Total is: " << (clock_period_ps + adjustment) << " ps.";
793	      clock_period_ps += adjustment;
794	    }
795	
796	    if (options.clock_period_ps().has_value()) {
797	      // If the user specified a clock period, and it's at least as long as our
798	      // relaxed minimum clock period, use that instead; no need to squeeze the
799	      // stages for a tighter clock than the user's target.
800	      if (VLOG_IS_ON(4) && clock_period_ps < *options.clock_period_ps()) {
801	        VLOG(4) << "User-specified clock period of "
802	                << *options.clock_period_ps() << " is greater than minimum "
803	                << "feasible clock period of " << clock_period_ps
804	                << " ps; using user-specified clock period.";
805	      }
806	      clock_period_ps = std::max(clock_period_ps, *options.clock_period_ps());
807	    }
808	
809	    if (options.clock_period_ps().has_value() &&
810	        clock_period_ps > *options.clock_period_ps()) {
811	      CHECK(options.minimize_clock_on_failure().value_or(false));
812	      CHECK(options.recover_after_minimizing_clock().value_or(false));
813	      LOG(WARNING) << "Target clock period was " << *options.clock_period_ps()
814	                   << ", but shortest feasible clock period (after any "
815	                      "specified relaxation) is "
816	                   << clock_period_ps
817	                   << " ps; continuing with clock period = " << clock_period_ps
818	                   << " ps.";
819	    }
820	    VLOG(4) << "Got clock period of " << clock_period_ps << " from minimum.";
821	  } else {
822	    VLOG(4) << "Got clock period of " << options.clock_period_ps().value()
823	            << " from options.";
824	    clock_period_ps = options.clock_period_ps().value();
825	  }
826	
827	  XLS_ASSIGN_OR_RETURN(clock_period_ps,
828	                       ApplyClockMargin(options, clock_period_ps));
829	
830	  // Only actually attempt to minimize WCT if we are (1) told we can do so,
831	  // (2) we don't have an explicitly chosen WCT already, and (3) we have a
832	  // constraint that actually cares about WCT.
833	  // TODO(allight): Does it actually make sense to ever not have a back-edge
834	  // constraint with a WCT setting?
835	  if (options.minimize_worst_case_throughput() && f->IsProc() &&
836	      !worst_case_throughput &&
837	      absl::c_any_of(
838	          options.constraints(), [](const SchedulingConstraint& constraint) {
839	            return std::holds_alternative<BackedgeConstraint>(constraint);
840	          })) {
841	    XLS_RETURN_IF_ERROR(initialize_bounds_scheduler());
842	    absl::StatusOr<int64_t> wct = FindMinimumWorstCaseThroughput(
843	        f->AsProcOrDie(), options.pipeline_stages(), clock_period_ps,
844	        *bounds_scheduler,
845	        /*failure_behavior=*/{.explain_infeasibility = false});
846	    if (wct.ok()) {
847	      worst_case_throughput = *wct;
848	      LOG(INFO) << "Minimized worst-case throughput for proc '" << f->name()
849	                << "': " << *worst_case_throughput;
850	    } else {
851	      VLOG(2) << "Failed to minimize worst-case throughput for proc '"
852	              << f->name() << "', continuing to allow normal error handling: "
853	              << wct.status();
854	    }
855	  }
856	
857	  // Worst case throughput is either known from the options, the proc itself, or
858	  // minimization by now. Notate it in the proc itself.
859	  //
860	  // Using a helper since other parts of codegen/sched/other tools use the same
861	  // nullopt interpretation as the scheduling_options flag. See comment on
862	  // function for more information.
863	  SetWorstCaseThroughput(worst_case_throughput, f);
864	
865	  // TODO(allight): Rewrite FDO into the scheduler API.
866	  if (options.use_fdo() && options.strategy() == SchedulingStrategy::SDC) {
867	    if (f->IsProc()) {
868	      XLS_RET_CHECK_EQ(f->AsProcOrDie()->GetInitiationInterval().has_value(),
869	                       worst_case_throughput.has_value())
870	          << " ii: " << f->AsProcOrDie()->GetInitiationInterval().value_or(-1)
871	          << " wct: " << worst_case_throughput.value_or(-1);
872	      if (worst_case_throughput) {
873	        XLS_RET_CHECK_EQ(*f->AsProcOrDie()->GetInitiationInterval(),
874	                         *worst_case_throughput);
875	      }
876	    }
877	    return RunIterativeSDCSchedule(f, options, clock_period_ps, delay_estimator,
878	                                   synthesizer);
879	  } else if (options.use_fdo()) {
880	    return absl::InvalidArgumentError(
881	        "FDO is only supported with SDC strategy.");
882	  }
883	  VLOG(4) << "Starting primary scheduling. Failure behavior is: "
884	          << options.failure_behavior().ToProto().ShortDebugString();
885	  ScheduleCycleMap cycle_map;
886	  XLS_RETURN_IF_ERROR(initialize_scheduler());
887	  absl::StatusOr<ScheduleCycleMap> schedule_cycle_map =
888	      scheduler->Schedule(options.pipeline_stages(), clock_period_ps,
889	                          options.failure_behavior(), worst_case_throughput);
890	
891	  if (!schedule_cycle_map.ok()) {
892	    XLS_RETURN_IF_ERROR(initialize_bounds_scheduler());
893	    return HandleScheduleFailure(std::move(schedule_cycle_map).status(), graph,
894	                                 options, worst_case_throughput, io_delay_added,
895	                                 min_clock_period_ps_for_tracing,
896	                                 clock_period_ps, *bounds_scheduler);
897	  }
898	  cycle_map = *std::move(schedule_cycle_map);
899	
900	  XLS_ASSIGN_OR_RETURN(
901	      PipelineSchedule schedule,
902	      PipelineSchedule::Create(
903	          f, cycle_map,
904	          {.length = options.pipeline_stages(),
905	           .min_clock_period_ps = min_clock_period_ps_for_tracing,
906	           .target_clock_period_ps = clock_period_ps}));
907	  XLS_VLOG_LINES(5, "Schedule\n" + schedule.ToString());
908	  XLS_RETURN_IF_ERROR(schedule.Verify());
909	  XLS_RETURN_IF_ERROR(schedule.VerifyTiming(clock_period_ps, io_delay_added));
910	  XLS_RETURN_IF_ERROR(
911	      schedule.VerifyConstraints(options.constraints(), options));
912	
913	  return schedule;
914	}
915	
916	}  // namespace
917	
918	absl::StatusOr<PipelineSchedule> RunPipelineSchedule(
919	    FunctionBase* f, const DelayEstimator& delay_estimator,
920	    const SchedulingOptions& options,
921	    std::optional<const ProcElaboration*> elab) {
922	  return RunPipelineScheduleInternal(f, delay_estimator, options, elab,
923	                                     /*synthesizer=*/nullptr);
924	}
925	
926	absl::StatusOr<PipelineSchedule> RunPipelineScheduleWithFdo(
927	    FunctionBase* f, const DelayEstimator& delay_estimator,
928	    const SchedulingOptions& options, const synthesis::Synthesizer& synthesizer,
929	    std::optional<const ProcElaboration*> elab) {
930	  return RunPipelineScheduleInternal(f, delay_estimator, options, elab,
931	                                     &synthesizer);
932	}
933	
934	absl::StatusOr<PackageSchedule> RunSynchronousPipelineSchedule(
935	    Package* package, const DelayEstimator& delay_estimator,
936	    const SchedulingOptions& options, const ProcElaboration& elab) {
937	  // TODO(https://github.com/google/xls/issues/2175): Synchronous scheduling
938	  // currently only supports a clock period option.
939	  XLS_RET_CHECK(options.clock_period_ps().has_value());
940	  XLS_RET_CHECK(!options.pipeline_stages().has_value());
941	  XLS_RET_CHECK(!options.worst_case_throughput().has_value());
942	  XLS_RET_CHECK(!options.clock_margin_percent().has_value());
943	  XLS_RET_CHECK(!options.period_relaxation_percent().has_value());
944	  XLS_RET_CHECK(!options.use_fdo());
945	  XLS_RET_CHECK(!options.additional_input_delay_ps().has_value());
946	  XLS_RET_CHECK(!options.additional_output_delay_ps().has_value());
947	  XLS_RET_CHECK(options.strategy() == SchedulingStrategy::SDC);
948	
949	  // TODO(https://github.com/google/xls/issues/2175): Current limitations are
950	  // that all sends and receives mush be unconditional and procs can only be
951	  // instantiated once.
952	  for (Proc* proc : elab.procs()) {
953	    if (elab.GetInstances(proc).size() != 1) {
954	      return absl::UnimplementedError(
955	          absl::StrFormat("Proc `%s` is instantiated more than once which is "
956	                          "not supported with synchronous procs.",
957	                          proc->name()));
958	    }
959	    for (Node* node : proc->nodes()) {
960	      if (node->Is<ChannelNode>() &&
961	          node->As<ChannelNode>()->predicate().has_value()) {
962	        return absl::UnimplementedError(
963	            absl::StrFormat("Send/receive node `%s` is predicated which is not "
964	                            "supported with synchronous procs.",
965	                            node->GetName()));
966	      }
967	    }
968	  }
969	
970	  XLS_ASSIGN_OR_RETURN(
971	      ScheduleGraph graph,
972	      ScheduleGraph::CreateSynchronousGraph(package, /*loopback_channels=*/{},
973	                                            elab, /*dead_after_synthesis=*/{}));
974	
975	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<SDCScheduler> sdc_scheduler,
976	                       SDCScheduler::Create(graph, delay_estimator, options));
977	  XLS_RETURN_IF_ERROR(sdc_scheduler->AddConstraints(options.constraints()));
978	
979	  XLS_ASSIGN_OR_RETURN(
980	      ScheduleCycleMap cycle_map,
981	      sdc_scheduler->Schedule(std::nullopt, *options.clock_period_ps(),
982	                              options.failure_behavior()));
983	
984	  // Convert the global cycle map of all nodes in the package to individual
985	  // schedules for each proc.
986	  //
987	  // * For the top-level proc, the schedule cycle for each node X is the cycle
988	  //   in the global schedule (cycle_map[X]).
989	  //
990	  // * For all other procs, the schedule cycle for a node X is cycle_map[X]
991	  //   minus the minimum cycle for any node in the proc.
992	  //
993	  // The computed adjustments for each proc are saved in `synchronous_offsets`.
994	  absl::flat_hash_map<FunctionBase*, int64_t> synchronous_offsets;
995	  // Iterate through the proc hierarchy from the bottom up.
996	  for (auto it = elab.procs().crbegin(); it != elab.procs().crend(); ++it) {
997	    Proc* proc = *it;
998	
999	    int64_t earliest_stage;
1000	    if (proc == elab.top()->proc() || proc->node_count() == 0) {
1001	      earliest_stage = 0;
1002	    } else {
1003	      earliest_stage = std::numeric_limits<int64_t>::max();
1004	      for (Node* node : proc->nodes()) {
1005	        if (IsUntimed(node)) {
1006	          continue;
1007	        }
1008	        earliest_stage = std::min(earliest_stage, cycle_map.at(node));
1009	      }
1010	    }
1011	    synchronous_offsets[proc] = earliest_stage;
1012	  }
1013	
1014	  PackageSchedule::ScheduleMap schedule_map;
1015	  for (Proc* proc : elab.procs()) {
1016	    absl::flat_hash_map<Node*, int64_t> proc_cycle_map;
1017	    for (Node* node : proc->nodes()) {
1018	      if (IsUntimed(node)) {
1019	        continue;
1020	      }
1021	      proc_cycle_map[node] = cycle_map.at(node) - synchronous_offsets.at(proc);
1022	    }
1023	    XLS_ASSIGN_OR_RETURN(schedule_map[proc],
1024	                         PipelineSchedule::Create(proc, proc_cycle_map));
1025	  }
1026	
1027	  PackageSchedule package_schedule(package, std::move(schedule_map),
1028	                                   std::move(synchronous_offsets));
1029	  VLOG(2) << package_schedule.ToString();
1030	  return package_schedule;
1031	}
1032	
1033	}  // namespace xls
